\section{The design calculus}\label{sec:calculus}

Throughout, the sample is a finite index set, and features and residuals are real
vectors indexed by it.

\begin{definition}[design inner product]
$\ip{x}{y}=\sum_i x_i y_i$ and $\nm{x}^2=\ip{x}{x}$. For a family $(f_k)_{k}$ and
coefficients $a$, the combination is $\combo(a,f)_i=\sum_k a_k f_k(i)$.
\end{definition}

\begin{definition}[gain]
For $f\neq0$, $\displaystyle \gainop(e,f)=\frac{\ip{e}{f}^2}{\nm{f}^2}$.
\end{definition}

\begin{proposition}[single-feature projection identity]\label{prop:proj}
If $\nm{f}^2\neq0$ then
$\big\| e - \tfrac{\ip{e}{f}}{\nm{f}^2} f\big\|^2 = \nm{e}^2-\gainop(e,f)$.
\end{proposition}

\begin{proof}
Expand $\nm{e-cf}^2=\nm{e}^2-2c\ip{e}{f}+c^2\nm{f}^2$ and substitute
$c=\ip{e}{f}/\nm{f}^2$.
\end{proof}

Thus $\gainop(e,f)$ is exactly the residual energy removed by least squares, and
$\gainop(e,f)/\nm{e}^2$ is the incremental $R^2$.

\begin{proposition}
$0\le\gainop(e,f)\le\nm{e}^2$, the upper bound being Cauchy--Schwarz.
\end{proposition}

\begin{proposition}[orthogonal additivity]\label{prop:orthadd}
If the $f_k$ are pairwise orthogonal with $\nm{f_k}^2>0$, then with
$c_k=\ip{e}{f_k}/\nm{f_k}^2$,
\[
\big\|e-\combo(c,f)\big\|^2=\nm{e}^2-\sum_k \gainop(e,f_k).
\]
\end{proposition}

\begin{proof}
Orthogonality gives $\ip{e}{\combo(c,f)}=\sum_k\gainop(e,f_k)$ and
$\nm{\combo(c,f)}^2=\sum_k c_k^2\nm{f_k}^2=\sum_k\gainop(e,f_k)$; substitute into
$\nm{e-g}^2=\nm{e}^2-2\ip{e}{g}+\nm{g}^2$.
\end{proof}

\section{The sub-threshold lift ceiling}\label{sec:ceiling}

The obstruction to summing per-feature gains is that a combination of correlated
features can be short, and shortness inflates the gain, whose denominator is
$\nm{g}^2$. The following bound rules that out.

\begin{theorem}[stability from Gram off-diagonals]\label{thm:stab}
Let $f_1,\dots,f_K$ satisfy $|\ip{f_k}{f_l}|\le\delta\nm{f_k}\nm{f_l}$ for
$k\neq l$, with $\delta\ge0$. Then for every $a$,
\[
\big(1-\delta(K-1)\big)\sum_k a_k^2\nm{f_k}^2 \;\le\; \Big\|\sum_k a_k f_k\Big\|^2 .
\]
\end{theorem}

\begin{proof}
Put $w_k=|a_k|\nm{f_k}$, $Q=\sum_k w_k^2$, $W=\sum_k w_k$. Off the diagonal,
$a_ka_l\ip{f_k}{f_l}\ge-\delta w_kw_l$; on the diagonal the term equals $w_k^2$.
Summing, $\nm{\sum_k a_kf_k}^2\ge(1+\delta)Q-\delta W^2$. Cauchy--Schwarz gives
$W^2\le KQ$, whence the bound $\ge(1+\delta-\delta K)Q$.
\end{proof}

\begin{theorem}[sub-threshold lift ceiling]\label{thm:ceiling}
Let $\nm{f_k}^2>0$ and $\ip{e}{f_k}^2\le\varepsilon^2\nm{e}^2\nm{f_k}^2$ for each
$k$, and suppose the design is a restricted isometry with constant $1-\delta>0$,
i.e.\ $(1-\delta)\sum_k a_k^2\nm{f_k}^2\le\nm{\combo(a,f)}^2$ for all $a$. Then
for every $a$,
\[
\gainop\big(e,\combo(a,f)\big)\;\le\;\frac{K\varepsilon^2}{1-\delta}\,\nm{e}^2 .
\]
\end{theorem}

\begin{proof}
Set $A=\sum_k a_k^2\nm{f_k}^2$, $u_k=a_k\nm{f_k}$, $v_k=\ip{e}{f_k}/\nm{f_k}$, so
$u_kv_k=a_k\ip{e}{f_k}$ and $\ip{e}{\combo(a,f)}=\sum_k u_kv_k$. Cauchy--Schwarz
and $v_k^2\le\varepsilon^2\nm{e}^2$ give
$\ip{e}{\combo(a,f)}^2\le A\cdot K\varepsilon^2\nm{e}^2$, while the restricted
isometry gives $A\le\nm{\combo(a,f)}^2/(1-\delta)$. Dividing by
$\nm{\combo(a,f)}^2$ eliminates it, and $a$, entirely.
\end{proof}

\begin{corollary}[ceiling from Gram data alone]\label{cor:gram}
If moreover $|\ip{f_k}{f_l}|\le\delta_0\nm{f_k}\nm{f_l}$ for $k\ne l$ with
$\delta_0(K-1)<1$, then
$\gainop(e,\combo(a,f))\le \dfrac{K\varepsilon^2}{1-\delta_0(K-1)}\nm{e}^2$.
\end{corollary}

Both inputs are measurable \emph{before} fitting: the $K$ marginal correlations
and the $\binom K2$ feature correlations.

\begin{theorem}[block additivity ceiling]\label{thm:blocks}
Let $g_b$ be pairwise orthogonal nonzero vectors. Then
$\gainop\big(e,\sum_b g_b\big)\le\sum_b\gainop(e,g_b)$.
\end{theorem}

\begin{proof}
With $G=\sum_b g_b$, orthogonality gives $\ip{e}{G}=\sum_b\ip{e}{g_b}$ and
$\nm{G}^2=\sum_b\nm{g_b}^2$. Cauchy--Schwarz on $u_b=\ip{e}{g_b}/\nm{g_b}$,
$v_b=\nm{g_b}$ yields $\ip{e}{G}^2\le\big(\sum_b\gainop(e,g_b)\big)\nm{G}^2$.
\end{proof}

\section{Arithmetic evaluation of the constants}\label{sec:arith}

Fix a modulus $N\ge1$ and write $\psi(x)=e^{2\pi i x/N}$ for the standard additive
character of $\Z/N$.

\begin{definition}
For $k\in\Z/N$ set $\cos_k(r)=\operatorname{Re}\psi(kr)$ and
$\sin_k(r)=\operatorname{Im}\psi(kr)$, as vectors indexed by $r\in\Z/N$.
\end{definition}

\begin{lemma}[complete character sum]\label{lem:charsum}
$\sum_{r\in\Z/N}\psi(tr)=N$ if $t=0$, and $0$ otherwise.
\end{lemma}

\begin{theorem}[exact trigonometric Gram]\label{thm:trig}
For all $k,l\in\Z/N$,
\[
\ip{\cos_k}{\cos_l}=\tfrac12\big(N[k=l]+N[k=-l]\big),\qquad
\ip{\sin_k}{\sin_l}=\tfrac12\big(N[k=l]-N[k=-l]\big),
\]
\[
\ip{\cos_k}{\sin_l}=0\quad\text{for all }k,l.
\]
In particular $\nm{\cos_k}^2=\nm{\sin_k}^2=N/2$ when $k\ne0$ and $2k\ne0$;
distinct frequencies (up to sign) are exactly orthogonal; and cosines and sines are
exactly orthogonal at every pair of frequencies.
\end{theorem}

\begin{proof}
Using $\overline{\psi(x)}=\psi(-x)$,
\[
\cos_k(r)\cos_l(r)=\operatorname{Re}\tfrac{\psi((k-l)r)+\psi((k+l)r)}{2},\quad
\sin_k(r)\sin_l(r)=\operatorname{Re}\tfrac{\psi((k-l)r)-\psi((k+l)r)}{2},
\]
\[
\cos_k(r)\sin_l(r)=\operatorname{Im}\tfrac{\psi((k+l)r)-\psi((k-l)r)}{2}.
\]
Sum over $r$ and apply Lemma~\ref{lem:charsum}; in the third case the sums are the
real numbers $N$ or $0$, whose imaginary parts vanish.
\end{proof}

\begin{theorem}[cross-prime orthogonality]\label{thm:crt}
Let $p\ne q$ be odd primes and $N=pq$. Then $\ip{\cos_q}{\cos_p}=0$ over $\Z/N$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:trig} the inner product vanishes unless $q\equiv\pm p\pmod{pq}$,
which fails since $0<p+q<pq$ and $0<|p-q|<pq$.
\end{proof}

Theorem~\ref{thm:crt} is the Chinese Remainder Theorem in Gram form and supplies
exactly the hypothesis of Theorem~\ref{thm:blocks}: blocks for distinct primes are
mutually orthogonal, so the ceiling is additive over primes.

From now on let $p$ be an odd prime and $N=p$.

\begin{definition}
$\QR(r)=\left(\tfrac rp\right)\in\{-1,0,1\}$ is the quadratic character of $\Z/p$,
with $\QR(0)=0$.
\end{definition}

\begin{lemma}
$\nm{\QR}^2=p-1$.
\end{lemma}

\begin{definition}[Gauss sum]
$g_k=\sum_{r\in\Z/p}\QR(r)\psi(kr)$.
\end{definition}

By construction $\operatorname{Re}g_k=\ip{\QR}{\cos_k}$ and
$\operatorname{Im}g_k=\ip{\QR}{\sin_k}$: the entire coupling between the arithmetic
feature and the Fourier features is a Gauss sum.

\begin{theorem}[Gauss]\label{thm:gauss}
For $k\ne0$, $|g_k|^2=p$.
\end{theorem}

\begin{corollary}
For $k\ne0$, $|\ip{\QR}{\cos_k}|\le\sqrt p$ and $|\ip{\QR}{\sin_k}|\le\sqrt p$.
\end{corollary}

\begin{theorem}[normalised coupling]\label{thm:delta}
For an odd prime $p\ge3$ and $k$ with $k\ne0$, $2k\ne0$,
\[
\frac{|\ip{\QR}{\cos_k}|}{\nm{\QR}\nm{\cos_k}}\;\le\;\delta_p:=\sqrt{\frac{2}{p-1}},
\]
and likewise for $\sin_k$.
\end{theorem}

\begin{proof}
$\nm{\QR}\nm{\cos_k}=\sqrt{(p-1)p/2}$ and $\sqrt p/\sqrt{(p-1)p/2}=\sqrt{2/(p-1)}$.
\end{proof}

Numerically $\delta_5=0.7071$, $\delta_7=0.5774$, $\delta_{11}=0.4472$,
$\delta_{13}=0.4082$, $\delta_{29}=0.2673$: the coupling strictly decreases in $p$,
so larger primes make the design \emph{more} orthogonal.

\subsection{The Gauss-sign dichotomy}

Gauss's determination of the argument of the quadratic Gauss sum gives more than
the modulus: $g_k$ is real for $p\equiv1\pmod4$ and purely imaginary for
$p\equiv3\pmod4$.

\begin{theorem}[Gauss-sign dichotomy]\label{thm:dich}
Let $p$ be an odd prime and $k\ne0$.
\begin{itemize}
\item If $p\equiv3\pmod4$ then $\ip{\QR}{\cos_k}=0$ exactly and
$|\ip{\QR}{\sin_k}|=\sqrt p$ exactly.
\item If $p\equiv1\pmod4$ then $\ip{\QR}{\sin_k}=0$ exactly and
$|\ip{\QR}{\cos_k}|=\sqrt p$ exactly.
\end{itemize}
\end{theorem}

Consequently each three-feature prime block has exactly \emph{one} coupled pair,
determined by $p\bmod 4$, and the bound of Theorem~\ref{thm:delta} is attained in
the active channel.

\section{The sharp prime-block constant and its exactness}\label{sec:sharp}

\begin{definition}[prime block]
For an odd prime $p$ and a frequency $k$ with $k\ne0$, $2k\ne0$, the prime-$p$
block is $B_{p,k}=(\cos_k,\sin_k,\QR)$.
\end{definition}

Applying Corollary~\ref{cor:gram} crudely with $K=3$, $\delta_0=\delta_p$ gives the
constant $1-2\delta_p$, positive only for $p\ge13$ and useless for
$p\in\{5,7,11\}$. The dichotomy removes this defect.

\begin{theorem}[sharp stability for a single coupled pair]\label{thm:sharpstab}
Let $f_0,f_1,f_2$ be nonzero with $f_0$ exactly orthogonal to $f_1$ and $f_2$, and
$|\ip{f_1}{f_2}|\le\delta\nm{f_1}\nm{f_2}$, $\delta\ge0$. Then for all $a$,
\[
(1-\delta)\sum_j a_j^2\nm{f_j}^2\;\le\;\Big\|\sum_j a_jf_j\Big\|^2 .
\]
\end{theorem}

\begin{proof}
The only off-diagonal contribution is
$2a_1a_2\ip{f_1}{f_2}\ge-2\delta|a_1|\nm{f_1}|a_2|\nm{f_2}
\ge-\delta(a_1^2\nm{f_1}^2+a_2^2\nm{f_2}^2)$ by AM--GM. Add the diagonal. The use
of AM--GM in place of the Cauchy--Schwarz pile-up of Theorem~\ref{thm:stab} is
exactly what removes the factor $K-1=2$.
\end{proof}

\begin{corollary}\label{cor:blockstab}
For every odd prime $p\ge5$ and admissible $k$, the block $B_{p,k}$ satisfies the
restricted-isometry inequality with constant $1-\delta_p$, in both residue classes
of $p$ modulo $4$.
\end{corollary}

\begin{theorem}[exactness]\label{thm:exact}
For every odd prime $p\ge5$ the constant $1-\delta_p$ is optimal: no
$c>1-\delta_p$ satisfies $c\sum_j a_j^2\nm{f_j}^2\le\nm{\sum_j a_jf_j}^2$ for all
$a$.
\end{theorem}

\begin{proof}
Since the active coupling is exactly $\delta_p$ in normalised terms
(Theorem~\ref{thm:dich}), take the witness supported on the coupled pair with
$a_j=\mp\sigma/\nm{f_j}$ chosen so the cross term is maximally negative. Then
$\nm{\sum_j a_jf_j}^2=2\sigma^2(1-\delta_p)$ while
$\sum_j a_j^2\nm{f_j}^2=2\sigma^2$.
\end{proof}

Thus $1-\delta_p$ is the exact smallest eigenvalue of the normalised block Gram
matrix; no argument that sees only the Gram matrix can improve the ceiling.

\begin{theorem}[arithmetic block ceiling]\label{thm:blockceil}
Let $p\ge5$ be an odd prime, $k$ admissible, $e$ a residual, and suppose each of
the three block features has residual correlation at most $\varepsilon$. Then for
every $a\in\R^3$,
\[
\gainop\big(e,\combo(a,B_{p,k})\big)\;\le\;\frac{3\varepsilon^2}{1-\sqrt{2/(p-1)}}\nm{e}^2
\;\le\;\frac{3\varepsilon^2}{0.292}\nm{e}^2 .
\]
\end{theorem}

For $p\ge13$ one may use $\delta_p\le0.41$, giving $3\varepsilon^2/0.59$; the
improvement over the crude $1-2\delta$ is a factor $0.59/0.18>3$.

