\section{The numerical certificate and the deterministic refutation}\label{sec:cert}

\begin{theorem}[sub-threshold certificate]\label{thm:cert}
Nine mutually orthogonal prime blocks, each of three features with per-feature
residual correlation at most $\varepsilon=0.01$ and worst-case block constant
$0.292$, together lift at most
\[
9\cdot\frac{3(0.01)^2}{0.292}=0.00925\le0.01
\]
of the residual energy.
\end{theorem}

Restricting to $p\ge13$, the constant $0.59$ gives $9\cdot3\cdot10^{-4}/0.59
=0.00458\le0.005$.

\begin{theorem}[the registered hypothesis is unreachable]\label{thm:h3}
With a baseline $R^2=0.600$ the residual carries $0.400$ of the total variance, so
the best possible phase-augmented score is $0.600+0.01\cdot0.400=0.604<0.70$; under
the $p\ge13$ certificate, $0.600+0.005\cdot0.400=0.602<0.70$.
\end{theorem}

The observed $+0.008$ lift is $0.008/0.400=0.02$ of the residual energy, which the
ceiling accommodates at $\varepsilon=0.0116$: the measured lift is consistent with
per-feature correlations of barely one percent.

\section{Full-frequency degeneracy}\label{sec:degen}

\begin{definition}[frequency half-period]
For an odd prime $p$ let $H_p\subseteq\Z/p$ be the image of $\{1,\dots,(p-1)/2\}$,
of cardinality $(p-1)/2$; it contains no $0$ and no pair $k,-k$, so
$\{\cos_k,\sin_k:k\in H_p\}$ is pairwise orthogonal by Theorem~\ref{thm:trig}.
\end{definition}

\begin{lemma}[two units per frequency]\label{lem:two}
For $k\ne0$,
\[
\gainop(\QR,\cos_k)+\gainop(\QR,\sin_k)
=\frac{(\operatorname{Re}g_k)^2+(\operatorname{Im}g_k)^2}{p/2}=\frac{2|g_k|^2}{p}=2 .
\]
\end{lemma}

\begin{theorem}[Bessel equality]\label{thm:bessel}
$\displaystyle\sum_{k\in H_p}\big(\gainop(\QR,\cos_k)+\gainop(\QR,\sin_k)\big)
=2\cdot\frac{p-1}{2}=p-1=\nm{\QR}^2 .$
\end{theorem}

\begin{theorem}[degeneracy]\label{thm:degen}
The quadratic-residue indicator is exactly a linear combination of the half-period
phase features:
\[
\QR=\sum_{k\in H_p}\left(\frac{\ip{\QR}{\cos_k}}{\nm{\cos_k}^2}\cos_k
+\frac{\ip{\QR}{\sin_k}}{\nm{\sin_k}^2}\sin_k\right).
\]
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:orthadd} the residual after fitting the orthogonal
half-period family has energy $\nm{\QR}^2-\sum\gainop=(p-1)-(p-1)=0$ by
Theorem~\ref{thm:bessel}; a vector of zero energy is zero.
\end{proof}

\begin{corollary}[no incremental capacity]
For any $a$ and any coefficients $c$, the model $a\QR+\combo(c,\text{phases})$
equals $\combo(c',\text{phases})$ for explicit $c'$. Hence appending $\QR$ to a
full-frequency phase design cannot change any fitted value, residual, or $R^2$.
\end{corollary}

The coupling constant $\delta_p$, and with it the entire block-stability
discussion, is therefore a consequence of restricting to one frequency per prime:
a feature-selection effect, not an information-theoretic one.

\section{Window locality: what a negative score certifies}\label{sec:window}

Least squares cannot produce a negative gain on its own training data, so the
observed $-0.077$ must come from transport.

\begin{definition}
For a residual $e$ and feature $f$ on the test window and a transported
coefficient $b$, put
$\gainop_{\mathrm{oos}}(e,f,b)=\nm{e}^2-\nm{e-bf}^2$ and
$\beta^\star=\ip{e}{f}/\nm{f}^2$.
\end{definition}

\begin{theorem}[transported gain is an exact parabola]\label{thm:parab}
$\gainop_{\mathrm{oos}}(e,f,b)=2b\ip{e}{f}-b^2\nm{f}^2
=\nm{f}^2\big((\beta^\star)^2-(b-\beta^\star)^2\big).$
\end{theorem}

\begin{corollary}[transfer identity]
The shortfall against the test window's own optimum is exactly
$(b-\beta^\star)^2\nm{f}^2$, nothing else.
\end{corollary}

\begin{corollary}[in-window dominance]\label{cor:dom}
$\gainop_{\mathrm{oos}}(e,f,b)\le\gainop(e,f)$ for every $b$, with equality iff
$b=\beta^\star$. In particular no rescaling $b\mapsto\lambda b$ of a transported
coefficient can beat the test window's own single-feature gain.
\end{corollary}

\begin{corollary}[sign mismatch]\label{cor:sign}
If $b\ne0$ and $b\ip{e}{f}\le0$ then
$\gainop_{\mathrm{oos}}(e,f,b)\le-b^2\nm{f}^2<0$.
\end{corollary}

\begin{corollary}[negativity is a coefficient miss]
$\gainop_{\mathrm{oos}}(e,f,b)<0$ if and only if $|b-\beta^\star|>|\beta^\star|$.
\end{corollary}

\begin{theorem}[quantitative miss]\label{thm:miss}
If $\gainop_{\mathrm{oos}}(e,f,b)\le-\rho\nm{e}^2$ with $\rho>0$, then
$(b-\beta^\star)^2\ge\rho\,\nm{e}^2/\nm{f}^2$; i.e.\ the standardized miss
$|b-\beta^\star|\nm{f}/\nm{e}$ is at least $\sqrt\rho$.
\end{theorem}

\begin{corollary}[measured certificates]\label{cor:measured}
The phase-only arm scored $-0.077$, certifying a standardized coefficient miss of
at least $\sqrt{0.077}=0.277$. The baseline degraded from $0.600$ in-window to
$0.400$ cross-window, certifying a miss of at least $\sqrt{0.200}=0.447$. Hence the
baseline is itself window-local, by a larger margin than the phase block.
\end{corollary}

\begin{theorem}[transport cannot evade the ceiling]
Under the hypotheses of Theorem~\ref{thm:ceiling}, for any $a$ learned on any
window and any rescaling $b$,
$\gainop_{\mathrm{oos}}(e,\combo(a,f),b)\le\frac{K\varepsilon^2}{1-\delta}\nm{e}^2$.
\end{theorem}

\begin{proof}
Corollary~\ref{cor:dom} then Theorem~\ref{thm:ceiling}.
\end{proof}

\section{Separating the two surviving explanations}\label{sec:sep}

Two candidate explanations of the residual anomaly (an excess of roughly
$\Delta=0.2$) remain, and the theory separates them sharply.

\subsection{Candidate 1: higher primes}

\begin{theorem}[aggregate block ceiling]
If $n$ mutually orthogonal blocks each lift at most $c\nm{e}^2$, their sum lifts at
most $nc\nm{e}^2$.
\end{theorem}

\begin{theorem}[cost of higher primes]\label{thm:cost}
If $n$ prime blocks, each capped at $3\varepsilon^2/0.18$ of the residual energy,
are to cover an excess $\Delta$, then $n\ge 0.06\,\Delta/\varepsilon^2$.
\end{theorem}

\begin{corollary}
At $\Delta=0.2$ and $\varepsilon=0.01$, at least $120$ orthogonal prime blocks are
required. The design supplied nine; even all odd primes below $700$ would be
marginal.
\end{corollary}

\subsection{Candidate 2: same-window leakage}

Model a leaked feature as $f=\alpha e+g$ with $g\perp e$.

\begin{theorem}[leakage identity]\label{thm:leak}
If $\ip{e}{g}=0$ then
$\gainop(e,\alpha e+g)=\dfrac{\alpha^2\nm{e}^4}{\alpha^2\nm{e}^2+\nm{g}^2}$, so the
in-window $R^2$ equals the leaked fraction of the feature's energy.
\end{theorem}

\begin{corollary}[inverting the split]
A measured in-window $R^2=r<1$ pins $\alpha^2\nm{e}^2=\frac{r}{1-r}\nm{g}^2$; at
$r=0.6$ the leaked component carries $1.5$ times the energy of everything else in
the feature.
\end{corollary}

\begin{theorem}[model-free falsification test]\label{thm:falsify}
Any feature achieving in-window $R^2\ge0.6$ satisfies
$\ip{e}{f}^2\ge0.6\nm{e}^2\nm{f}^2$, i.e.\ correlates with the \emph{realized}
target at level at least $\sqrt{0.6}>0.774$.
\end{theorem}

\begin{theorem}[signature of leakage]
Suppose $f=\alpha e+g$ with $\alpha>0$, $g\perp e$, and the leaked component is
absent on the test window, so the test covariance vanishes. Then the in-window
coefficient $\beta=\ip{e}{f}/\nm{f}^2>0$ produces a strictly negative
out-of-sample gain.
\end{theorem}

\begin{proof}
Corollary~\ref{cor:sign} with $b=\beta\ne0$ and vanishing test covariance.
\end{proof}

Leakage reproduces any in-window $R^2$ with arbitrarily small genuine predictive
content, at no cost in the number of features, and predicts precisely the observed
pattern of a large in-window score with a negative cross-window score.

\section{Discussion}\label{sec:disc}

\subsection{Summary}

The argument separates into a statistical layer --- the ceiling
$K\varepsilon^2/(1-\delta)$ and its block additivity --- and an arithmetic layer
that evaluates $\delta$: zero inside the Fourier part, zero between distinct
primes, and exactly $\sqrt{2/(p-1)}$ for the single coupled pair inside a prime
block. The consequences are a cap of $0.01$ on the lift, a best achievable score of
$0.604$ against a bar of $0.70$, a certified coefficient miss of at least $0.277$
for the transported phase model and $0.447$ for the baseline, a cost of at least
$120$ blocks for the higher-prime explanation, and a free, directly testable
prediction for the leakage explanation.

\subsection{Limitations}

\begin{enumerate}
\item $\varepsilon$ is an empirical input; the ceiling is a conditional
impossibility, whose force comes from $\varepsilon$ being measurable before fitting.
\item The exact Gram identities hold over a complete period; for samples not
equidistributed modulo $p$ they acquire discrepancy error terms and the effective
$\delta$ increases.
\item The ceiling bounds linear combinations. Products of phases across distinct
primes are themselves phases modulo the product, so a natural class of
interactions falls back within the framework, but general nonlinearities do not.
\item The block analysis fixes one frequency per prime; at full frequency
resolution the quadratic-residue feature degenerates entirely
(Theorem~\ref{thm:degen}).
\end{enumerate}

\subsection{Future work}

Quantify the degradation of $\delta$ for non-equidistributed samples via
exponential-sum discrepancy; extend to cubic and quartic residue indicators, whose
Gauss sums have the same modulus $\sqrt p$, and ask whether an analogue of the
sign dichotomy holds; run the model-free leakage test of
Theorem~\ref{thm:falsify} first, since it needs no fitting; and note that by
Theorem~\ref{thm:exact} any improvement of the ceiling must use distributional
information about the residual beyond its Gram data.

\subsection{Broader relevance}

Whenever a feature family is designed rather than learned --- Fourier features,
random projections, wavelet dictionaries, hash features --- its Gram matrix is
known in closed form, and the theorems of Section~\ref{sec:ceiling} convert that
knowledge into a hard, pre-fit ceiling on achievable $R^2$. Where the design has
arithmetic origin, classical exponential-sum bounds supply the Gram entries for
free. The lesson of the Gauss-sign dichotomy is especially clean: knowing the
argument of a character sum, not merely its modulus, halved the effective coupling
and tripled the strength of the ceiling.

