"""
Algorithm 3 — Transported-Coefficient Diagnostics: Window-Locality and Leakage Certificates.

A least-squares fit cannot score negatively on the window it was fitted to, so a
negative out-of-sample score is informative rather than merely bad.  The
transported gain is the exact parabola

    gain_oos(b) = 2 b <e,f> - b^2 ||f||^2 = ||f||^2 ( beta*^2 - (b - beta*)^2 ),

with beta* = <e,f>/||f||^2 the test window's own optimum.  Consequences, all
implemented here:

  * the shortfall against the test optimum is exactly (b - beta*)^2 ||f||^2;
  * gain_oos < 0 iff |b - beta*| > |beta*|;
  * a measured relative gain of -rho certifies a standardized coefficient miss
    of at least sqrt(rho);
  * a leaked feature f = alpha e + g with g orthogonal to e has in-window R^2
    equal to the leaked energy fraction, and any feature with in-window
    R^2 >= r must correlate with the realized target at level at least sqrt(r).

Complexity: O(n) in the sample size for the inner products; O(1) for every
certificate derived from already-measured scalars.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import List, Sequence

Vector = List[float]


def dot(x: Sequence[float], y: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(x, y))


def sqnorm(x: Sequence[float]) -> float:
    return dot(x, x)


def opt_coef(e: Sequence[float], f: Sequence[float]) -> float:
    """The test window's own least-squares coefficient beta*."""
    return dot(e, f) / sqnorm(f)


def oos_gain(e: Sequence[float], f: Sequence[float], b: float) -> float:
    """Residual energy removed on the test window by a transported coefficient b."""
    return 2.0 * b * dot(e, f) - b * b * sqnorm(f)


def transfer_deficit(e: Sequence[float], f: Sequence[float], b: float) -> float:
    """Shortfall against the test window's optimum: exactly (b - beta*)^2 ||f||^2."""
    beta = opt_coef(e, f)
    return (b - beta) ** 2 * sqnorm(f)


def certified_coefficient_miss(relative_gain: float) -> float:
    """
    From a measured relative out-of-sample gain (negative), the certified lower
    bound on the standardized coefficient miss |b - beta*| ||f|| / ||e||.
    """
    if relative_gain >= 0.0:
        return 0.0
    return math.sqrt(-relative_gain)


def leak_in_window_r2(alpha: float, energy_e: float, energy_g: float) -> float:
    """In-window R^2 of the leaked feature alpha*e + g, g orthogonal to e."""
    denom = alpha * alpha * energy_e + energy_g
    return 0.0 if denom == 0.0 else alpha * alpha * energy_e / denom


def leak_energy_ratio_from_r2(r: float) -> float:
    """Invert the leakage identity: an in-window R^2 of r pins the ratio at r/(1-r)."""
    if not 0.0 <= r < 1.0:
        raise ValueError("r must lie in [0, 1)")
    return r / (1.0 - r)


def leak_correlation_threshold(r: float) -> float:
    """Any feature with in-window R^2 >= r must correlate with the realized target
    at level at least sqrt(r).  A model-free falsification test."""
    if not 0.0 <= r <= 1.0:
        raise ValueError("r must lie in [0, 1]")
    return math.sqrt(r)


@dataclass
class WindowDiagnostics:
    measured_relative_gain: float
    certified_miss: float
    negative: bool
    interpretation: str


def diagnose(label: str, relative_gain: float) -> WindowDiagnostics:
    miss = certified_coefficient_miss(relative_gain)
    neg = relative_gain < 0.0
    if neg:
        note = (
            f"{label}: the transported coefficient misses the test window's own "
            f"optimum by at least {miss:.4f} standardized units -- more than the "
            f"optimum's own size, which is what makes the score negative."
        )
    else:
        note = f"{label}: non-negative gain; no window-locality certificate."
    return WindowDiagnostics(relative_gain, miss, neg, note)


if __name__ == "__main__":
    for label, g in (
        ("phase-only arm", -0.077),
        ("baseline, in-window 0.600 -> cross-window 0.400", -0.200),
    ):
        print(diagnose(label, g).interpretation)
    print()
    print(f"leakage: in-window R^2 = 0.60 pins the leaked/orthogonal energy ratio "
          f"at {leak_energy_ratio_from_r2(0.6):.3f}")
    print(f"leakage: any such feature must correlate with the realized target at "
          f"level >= {leak_correlation_threshold(0.6):.6f}")
